"use client"

// Bollard UI — glob-input · MIT licence · https://bollard-ui.vercel.app/components/glob-input

import * as React from "react"
import { Check, Minus, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { checkGlob, globstarHint, matchFiles, splitPatterns, type GlobIssue } from "@/components/glob-input/glob"

export * from "@/components/glob-input/glob"

/** Default messages. `{count}`, `{total}`, `{pattern}`, `{deeper}`, `{example}` are filled in. */
export const GLOB_MESSAGES = {
  summary: "{count} of {total} files match",
  "inner-globstar": "** only spans folders as a whole segment, so here it acts like *.",
  "dot-slash": "Paths are matched without a leading ./, so this matches nothing.",
  backslash: "Use / between folders. \\ escapes the next character.",
  "only-negations": "Only ! patterns, so nothing is included to exclude from.",
  case: "Matches nothing, but {count} files differ only in case.",
  none: "Matches none of the {total} files.",
  all: "Matches every file, {example} included.",
  shallow: "{pattern} stops at the first /, so it skips {count} files in subfolders.",
  use: "Use {fix}",
  excluded: "excluded by {pattern}",
  wouldAdd: "with **",
  list: "Files and whether they match",
}

export interface GlobInputProps extends Omit<React.ComponentProps<"input">, "value" | "defaultValue" | "onChange"> {
  /** The relative, "/"-separated paths the pattern runs against. */
  files: string[]
  /** Visible label. */
  label?: string
  /** Controlled pattern text. Several patterns are separated by spaces. */
  value?: string
  /** Initial pattern when uncontrolled. */
  defaultValue?: string
  /** Called with the text and the files it matches. */
  onValueChange?: (value: string, matches: string[]) => void
  /** Match letter case exactly, as Linux and git do. */
  caseSensitive?: boolean
  /** Override any of the default messages. */
  messages?: Partial<typeof GLOB_MESSAGES>
}

const fieldClass =
  "h-9 w-full min-w-0 rounded-md border bg-transparent px-3 font-mono text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 md:text-sm dark:bg-input/30 data-warning:border-amber-500 dark:data-warning:border-amber-400"
const fixClass =
  "inline-flex h-6 items-center gap-1 rounded-md border border-amber-500/40 px-2 font-mono font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
const fill = (template: string, values: Record<string, string | number>) =>
  template.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))

/**
 * A glob field (**, *, ?, [a-z], {a,b}, !negation) that runs the pattern live against a real file
 * list, so what it catches is never a guess. It flags patterns that match nothing or everything,
 * the `*` vs `**` mix-up (src/*.ts silently skipping src/utils/), `**` glued to a name (**.ts), a
 * leading ./, backslashes and case-only misses, with one-tap fixes, and flashes files as they flip.
 */
export function GlobInput({
  files,
  label = "Files to include",
  value,
  defaultValue = "",
  onValueChange,
  caseSensitive = true,
  messages,
  placeholder = "src/**/*.ts",
  id,
  className,
  ref,
  ...props
}: GlobInputProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const listRef = React.useRef<HTMLUListElement>(null)
  const previous = React.useRef<Map<string, boolean>>(null)
  const autoId = React.useId()
  const inputId = id ?? autoId
  const t = { ...GLOB_MESSAGES, ...messages }
  const text = value ?? inner
  const options = { caseSensitive }
  const results = matchFiles(splitPatterns(text), files, options)
  const count = results.filter((r) => r.match).length
  const issue = checkGlob(text, files, options)
  const hint = issue ? null : globstarHint(text, files, options)
  const added = new Set(hint?.added)

  const commit = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next, matchFiles(splitPatterns(next), files, options).filter((r) => r.match).map((r) => r.file))
  }

  // Flash the rows whose match flipped, so the effect of each keystroke is visible.
  React.useEffect(() => {
    const now = new Map(results.map((r) => [r.file, r.match]))
    const before = previous.current
    previous.current = now
    if (!before || !listRef.current || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return
    listRef.current.querySelectorAll<HTMLElement>("[data-file]").forEach((row) => {
      const file = row.dataset.file as string
      if (before.has(file) && before.get(file) !== now.get(file))
        row.animate([{ backgroundColor: now.get(file) ? "rgb(16 185 129 / .35)" : "rgb(148 163 184 / .35)" }, { backgroundColor: "transparent" }], { duration: 350, easing: "ease-out" })
    })
  })

  const issueText = (i: GlobIssue) =>
    fill(t[i.kind], { count: "count" in i ? i.count : 0, total: files.length, example: "example" in i && i.example ? i.example : "" })
  const warning = issue
    ? { text: issueText(issue), fix: "fix" in issue ? issue.fix : undefined, id: issue.kind }
    : hint
      ? { text: fill(t.shallow, { pattern: hint.pattern, count: hint.added.length }), fix: hint.fix, id: "shallow" }
      : null

  return (
    <div data-slot="glob-input" className={cn("grid w-full min-w-0 max-w-sm grid-cols-1 content-start gap-1.5", className)}>
      <label htmlFor={inputId} className="w-fit text-sm font-medium">
        {label}
      </label>
      <input
        ref={ref}
        id={inputId}
        type="text"
        autoCapitalize="none"
        autoCorrect="off"
        spellCheck={false}
        placeholder={placeholder}
        value={text}
        onChange={(event) => commit(event.target.value)}
        aria-describedby={`${inputId}-status`}
        data-warning={warning ? "" : undefined}
        className={fieldClass}
        {...props}
      />
      <div id={`${inputId}-status`} aria-live="polite" className="grid min-h-6 grid-cols-1 gap-1 text-xs">
        {warning && (
          <p data-warning-id={warning.id} className="flex gap-1.5 text-amber-700 dark:text-amber-400">
            <span className="flex h-6 shrink-0 items-center"><TriangleAlert aria-hidden className="size-3.5" /></span>
            <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
              <span className="py-1 [overflow-wrap:anywhere]">{warning.text}</span>
              {warning.fix && (
                <button type="button" onClick={() => commit(warning.fix as string)} className={cn(fixClass, "min-w-0 max-w-full")}>
                  <span className="truncate">{fill(t.use, { fix: warning.fix })}</span>
                </button>
              )}
            </span>
          </p>
        )}
        {text.trim() && <p className="py-1 text-muted-foreground">{fill(t.summary, { count, total: files.length })}</p>}
      </div>
      <ul ref={listRef} aria-label={t.list} className="max-h-60 overflow-auto rounded-md border py-1 font-mono text-xs">
        {results.map(({ file, match, excludedBy }) => (
          <li
            key={file}
            data-file={file}
            data-match={match || undefined}
            className="flex items-center gap-2 px-2.5 py-1 text-muted-foreground data-match:text-foreground"
          >
            {match ? (
              <Check aria-label="matches" className="size-3.5 shrink-0 text-emerald-600 dark:text-emerald-400" />
            ) : (
              <Minus aria-label="no match" className="size-3.5 shrink-0 opacity-50" />
            )}
            <span className={cn("min-w-0 truncate", excludedBy && "line-through decoration-muted-foreground/60")}>{file}</span>
            {excludedBy && <span className="ml-auto shrink-0 font-sans">{fill(t.excluded, { pattern: excludedBy })}</span>}
            {added.has(file) && (
              <span className="ml-auto shrink-0 rounded-sm border border-dashed border-amber-500/50 px-1 font-sans text-amber-700 dark:text-amber-400">{t.wouldAdd}</span>
            )}
          </li>
        ))}
      </ul>
    </div>
  )
}

// Bollard UI — glob-input · MIT licence · https://bollard-ui.vercel.app/components/glob-input

/** Expands the first top-level {a,b} group, recursively: "src/{app,lib}/*.{ts,tsx}" → four patterns. */
export function expandBraces(pattern: string, limit = 200): string[] {
  let depth = 0
  let start = -1
  for (let i = 0; i < pattern.length; i++) {
    const char = pattern[i]
    if (char === "\\") i++
    else if (char === "{" && depth++ === 0) start = i
    else if (char === "}" && depth > 0 && --depth === 0) {
      const body = pattern.slice(start + 1, i)
      const options: string[] = []
      let level = 0
      let from = 0
      for (let j = 0; j < body.length; j++) {
        if (body[j] === "{") level++
        else if (body[j] === "}") level--
        else if (body[j] === "," && level === 0) {
          options.push(body.slice(from, j))
          from = j + 1
        }
      }
      options.push(body.slice(from))
      if (options.length < 2) continue
      const head = pattern.slice(0, start)
      const tail = pattern.slice(i + 1)
      return options.flatMap((option) => expandBraces(head + option + tail, limit)).slice(0, limit)
    }
  }
  return [pattern]
}

const escape = (char: string) => char.replace(/[.+^$()|{}\\[\]]/g, "\\$&")

function segmentSource(segment: string) {
  let out = ""
  for (let i = 0; i < segment.length; i++) {
    const char = segment[i]
    if (char === "\\" && i + 1 < segment.length) out += escape(segment[++i])
    else if (char === "*") {
      while (segment[i + 1] === "*") i++ // "**" inside a segment is just "*"
      out += "[^/]*"
    } else if (char === "?") out += "[^/]"
    else if (char === "[" && segment.indexOf("]", i + 2) > i) {
      const end = segment.indexOf("]", i + 2)
      const body = segment.slice(i + 1, end).replace(/^[!^]/, "^").replace(/\\/g, "\\\\")
      out += `[${body}]`
      i = end
    } else out += escape(char)
  }
  return out
}

/**
 * Compiles one glob (no braces) to a RegExp over a "/"-separated relative path: `*` and `?` stay
 * inside one folder, `**` as a whole segment spans any number of folders (zero included), `[a-z]`
 * and `[!a]` are classes, a leading "/" anchors to the root. Like .gitignore, `*` also matches dotfiles.
 */
export function globToRegExp(glob: string, { caseSensitive = true } = {}) {
  const segments = glob.replace(/^\/+/, "").split("/")
  let source = ""
  segments.forEach((segment, i) => {
    const last = i === segments.length - 1
    if (segment === "**") source += last ? ".*" : "(?:[^/]+/)*"
    else source += segmentSource(segment) + (last ? "" : "/")
  })
  return new RegExp(`^${source}$`, caseSensitive ? "" : "i")
}

/** Splits the field into patterns (space separated) and expands braces in each. */
export function splitPatterns(text: string) {
  return text.trim().split(/\s+/).filter(Boolean)
}

/**
 * Evaluates patterns against files the way most tools (tsconfig, fast-glob, ESLint) do: a file is
 * in when it matches any positive pattern and no "!" pattern. Returns, per file, whether it is in and
 * which negation removed it.
 */
export function matchFiles(patterns: string[], files: string[], { caseSensitive = true } = {}) {
  const compile = (p: string) => expandBraces(p).map((g) => globToRegExp(g, { caseSensitive }))
  const include = patterns.filter((p) => !p.startsWith("!")).map((p) => compile(p))
  const exclude = patterns.filter((p) => p.startsWith("!")).map((p) => ({ pattern: p, res: compile(p.slice(1)) }))
  return files.map((file) => {
    const included = include.some((res) => res.some((re) => re.test(file)))
    const excludedBy = included ? exclude.find((e) => e.res.some((re) => re.test(file)))?.pattern : undefined
    return { file, match: included && !excludedBy, excludedBy }
  })
}

/** "src/*.ts" → "src/**\/*.ts"; "src/*\/index.ts" → "src/**\/index.ts": what `**` would have meant, or null. */
export function deeperPattern(pattern: string) {
  if (pattern.startsWith("!") || !pattern.includes("*") || pattern.includes("**")) return null
  const segments = pattern.split("/")
  const star = segments.slice(0, -1).lastIndexOf("*")
  if (star >= 0) return segments.map((s, i) => (i === star ? "**" : s)).join("/")
  return [...segments.slice(0, -1), "**", segments[segments.length - 1]].join("/")
}

export type GlobIssue =
  | { kind: "inner-globstar"; fix: string }
  | { kind: "dot-slash"; fix: string }
  | { kind: "backslash"; fix: string }
  | { kind: "only-negations"; fix: string }
  | { kind: "case"; count: number; fix?: string }
  | { kind: "none"; count: number }
  | { kind: "all"; count: number; example?: string }

/** The first thing wrong with a pattern list, given the files it runs against. */
export function checkGlob(text: string, files: string[], { caseSensitive = true } = {}): GlobIssue | null {
  const patterns = splitPatterns(text)
  if (!patterns.length) return null
  const replace = (fn: (p: string) => string) => patterns.map(fn).join(" ")
  if (patterns.some((p) => /[^/!]\*\*|\*\*[^/]/.test(p)))
    return { kind: "inner-globstar", fix: replace((p) => p.replace(/(^!?|\/)\*\*([^/*]+)/g, "$1**/*$2").replace(/([^/!*]+)\*\*(\/|$)/g, "$1*/**$2")) }
  if (patterns.some((p) => /^!?\.\//.test(p))) return { kind: "dot-slash", fix: replace((p) => p.replace(/^(!?)\.\//, "$1")) }
  if (patterns.some((p) => /\\(?![*?[\]{}!\\])/.test(p))) return { kind: "backslash", fix: replace((p) => p.replace(/\\/g, "/")) }
  if (patterns.every((p) => p.startsWith("!"))) return { kind: "only-negations", fix: `** ${text.trim()}` }

  const count = matchFiles(patterns, files, { caseSensitive }).filter((r) => r.match).length
  if (count === 0 && files.length) {
    const loose = matchFiles(patterns, files, { caseSensitive: false }).filter((r) => r.match).length
    if (caseSensitive && loose) {
      const lower = text.trim().toLowerCase()
      const fixCount = matchFiles(splitPatterns(lower), files).filter((r) => r.match).length
      return { kind: "case", count: loose, fix: fixCount ? lower : undefined }
    }
    return { kind: "none", count: files.length }
  }
  if (count === files.length && files.length > 1) {
    const example = [...files].sort((a, b) => b.split("/").length - a.split("/").length)[0]
    return { kind: "all", count, example }
  }
  return null
}

/** For `*` patterns: what switching to `**` would add (files in subfolders `*` can't reach). */
export function globstarHint(text: string, files: string[], { caseSensitive = true } = {}) {
  const patterns = splitPatterns(text)
  const now = new Set(matchFiles(patterns, files, { caseSensitive }).filter((r) => r.match).map((r) => r.file))
  for (const pattern of patterns) {
    const deeper = deeperPattern(pattern)
    if (!deeper) continue
    const next = patterns.map((p) => (p === pattern ? deeper : p))
    const added = matchFiles(next, files, { caseSensitive }).filter((r) => r.match && !now.has(r.file)).map((r) => r.file)
    if (added.length) return { pattern, deeper, fix: next.join(" "), added }
  }
  return null
}
